function renderCharacter(){gender=Math.random()<.5?'woman':'man';const svg=avatarSvg(gender);wrap.innerHTML=svg+'</svg>';round++;roundEl.textContent=`ROUND ${String(round).padStart(2,'0')}`;tag.textContent=`${pick(['NEW FACE','FRESH LOOK','STYLE SCAN','NEXT UP'])} · ${pick(['READY?','QUICK!','GO!'])}`;stage.classList.remove('scanning');void stage.offsetWidth;stage.classList.add('scanning');}
function tone(freq,duration=.08,type='sine'){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch(e){}}
function startGame(){score=0;streak=0;round=0;playing=true;scoreEl.textContent='00';streakEl.textContent='0';progress.style.width='0%';overlay.classList.add('hidden');renderCharacter();}
function endGame(){playing=false;const isBest=score>best;if(isBest){best=score;localStorage.setItem('snapsort-best',best)}bestEl.textContent=`BEST SCORE · ${best}`;orb.textContent=score>=10?'🏆':'↯';orb.style.background=score>=10?'#ffd66e':'var(--pink)';modalTitle.textContent=score>=10?'On a roll!':'Run over!';modalCopy.innerHTML=`You sorted <b style="color:var(--ink)">${score}</b> ${score===1?'face':'faces'} correctly${isBest?' — a new personal best!':''}`;rule.innerHTML=`<b>WOMAN</b> → tap left<br><b class="pink">MAN</b> → tap right<br>${score>=10?'Incredible reflexes. Go beat it!':'One wrong move ends the run. Try again!'}`;startBtn.textContent='PLAY AGAIN';overlay.classList.remove('hidden');}
function answer(choice){if(!playing)return;const correct=(gender==='woman'&&choice==='left')||(gender==='man'&&choice==='right');if(correct){score++;streak++;scoreEl.textContent=String(score).padStart(2,'0');streakEl.textContent=streak;progress.style.width=`${Math.min(100,(score%10)*10)}%`;feedback.textContent=pick(['NICE!','SNAP!','YES!','CLEAN!']);feedback.className='feedback good show';$('flash').classList.remove('on');void $('flash').offsetWidth;$('flash').classList.add('on');tone(580+Math.min(streak,12)*35,.1);wrap.classList.add('swap');setTimeout(()=>{feedback.className='feedback';wrap.classList.remove('swap');if(playing)renderCharacter()},180)}else{streak=0;streakEl.textContent='0';feedback.textContent='WRONG SIDE!';feedback.className='feedback bad show';stage.classList.add('shake');tone(150,.22,'triangle');setTimeout(()=>{feedback.className='feedback';stage.classList.remove('shake');endGame()},330)}}
$('left').addEventListener('click',()=>answer('left'));$('right').addEventListener('click',()=>answer('right'));startBtn.addEventListener('click',startGame);$('sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♪':'♫̸';e.currentTarget.setAttribute('aria-label',soundOn?'Mute sound':'Enable sound')});document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();answer('left')}if(e.key==='ArrowRight'){e.preventDefault();answer('right')}if((e.key===' '||e.key==='Enter')&&!playing){e.preventDefault();startGame()}});
renderCharacter();
})();
</script>
</body>
</html>

